export type Batch = {id:number; design:string; supplier:string; reference:string; ordered:number; received:number; available:number; cost_unit:number; created:string};
export type Order = {id:number; created:string; items:string; total:number; status:string; fulfillment?:string; shipping_fee?:number; subtotal?:number;customer?:{id:number;identifier:string;name:string};mode?:string|null;payment_status?:string|null;payment_method?:string|null;customer_email?:string|null;customer_name?:string|null;shipping_code?:string|null;shipping_name?:string|null;tracking_number?:string|null};
export type OrderDetails={mode:"test"|"live";customer_email:string;customer_name:string;customer_phone:string;shipping_code:string;shipping_name:string;shipping_kind:string;address:{line1?:string;line2?:string;postal_code?:string;city?:string};locker_code:string;invoice:{requested?:boolean;company?:string;tax_id?:string;address?:string};consents:Record<string,unknown>;payment_method:"payu"|"transfer"|"pickup";payment_status:string;paid_at:string|null;paid_amount:number;payment_note:string;carrier:string;tracking_number:string;tracking_url:string;shipped_at:string|null;note:string};
export type PaymentRecord={id:number;ext_order_id:string;provider_order_id:string|null;status:string;amount:number;environment:string;created:string;refunds:{id:number;amount:number;status:string;reason:string;created:string}[]};
export const paymentStatusText:Record<string,string>={unpaid:"Nieopłacone",pending:"Płatność w toku",paid:"Opłacone",failed:"Płatność nieudana",refunded:"Zwrócone",partially_refunded:"Częściowo zwrócone",cancelled:"Anulowane"};
export const paymentMethodText:Record<string,string>={payu:"PayU online",transfer:"Przelew",pickup:"Przy odbiorze"};
type OrderLine = {sku:string; variant_sku?:string; name?:string; size?:string; qty:number; unit_price:number;base_unit_price?:number;personalization_fee?:number;personalization?:OrderPrint;decoration_method?:string;preorder?:{note:string;until:string}};
type OrderDetail = Omit<Order, "items"> & {items:OrderLine[]; events:{id:number; status:string; created:string}[]; production:Task[]; details?:OrderDetails|null; payments?:PaymentRecord[]; demo?:boolean; transfer?:{recipient:string;account:string;title:string;amount:number}|null; returns?:StaffReturn[]; printed_lines?:{line_index:number;printed_qty:number}[]};
export type Task = {id:number; order_id:number; line_index:number; batch_id:number; design:string; status:string; created:string; updated:string; reference?:string; supplier?:string; order_status?:string;product_name?:string;size?:string;qty?:number;personalization?:OrderPrint;decoration_method?:string};
export type ActivityEvent = {id:number; kind:string; object_id:string; note:string; created:string};
export type Movement = {id:number; sku:string; delta:number; reason:string; created:string; source:string};
export type OperationsData = {orders:Order[]; inventory:Variant[]; batches:Batch[]; tasks:Task[]; activity:ActivityEvent[]; movements:Movement[]};
export const emptyOperationsData:OperationsData = {orders:[], inventory:[], batches:[], tasks:[], activity:[], movements:[]};
export const orderStatuses = ["nowe", "oczekuje_platnosci", "oplacone", "potwierdzone", "do_kompletacji", "nanoszenie_dtf", "kontrola_jakosci", "spakowane", "wyslane", "wydane", "wyslane_demo", "zwrot", "anulowane"];
const productionStatuses = ["oczekuje", "przygotowanie", "nanoszenie", "kontrola", "gotowe", "odrzucone"];
export const statusText:Record<string,string> = {nowe:"Nowe", oczekuje_platnosci:"Oczekuje na płatność", oplacone:"Opłacone", wyslane:"Wysłane", zwrot:"Zwrot", potwierdzone:"Potwierdzone", do_kompletacji:"Kompletacja", nanoszenie_dtf:"Nanoszenie DTF", kontrola_jakosci:"Kontrola jakości", spakowane:"Spakowane", wydane:"Wydane", wyslane_demo:"Wysłane (demo)", anulowane:"Anulowane", oczekuje:"Oczekuje", przygotowanie:"Przygotowanie", nanoszenie:"Nanoszenie transferu", kontrola:"Kontrola jakości", gotowe:"Gotowe", odrzucone:"Odrzucone"};
const activityText:Record<string,string> = {player:"Zawodnik",product:"Produkt",customer:"Konto klienta",order:"Zamówienie", stock:"Korekta stanu", transfer:"Transfery DTF", production:"Nanoszenie DTF", payment:"Płatność", settings:"Ustawienia", staff:"Pracownicy", "pos-sale":"Sprzedaż POS", fulfillment:"Realizacja", launch:"Uruchomienie", "stock-import":"Import magazynu", homepage:"Strona główna", "product-gallery":"Galeria"};
const sourceText:Record<string,string> = {admin:"Korekta ręczna", checkout:"Zamówienie online", orders:"Obsługa zamówienia", "pos-demo":"Sprzedaż POS (test)", pos:"Sprzedaż POS", "inventory-import":"Import magazynu"};
export const formatMoney = (value:number) => new Intl.NumberFormat("pl-PL", {style:"currency", currency:"PLN"}).format(value / 100);
export const formatDate = (value:string) => {const date = new Date(value); return Number.isNaN(date.getTime()) ? value : date.toLocaleString("pl-PL", {day:"2-digit", month:"2-digit", year:"numeric", hour:"2-digit", minute:"2-digit"});};
export const orderNumber = (id:number) => "ZS-" + String(id).padStart(5, "0");
export const isClosedOrder = (status:string) => ["anulowane", "wyslane_demo", "wydane", "wyslane", "zwrot"].includes(status);
export const isClosedTask = (status:string) => ["gotowe", "odrzucone"].includes(status);

export class AdminApiError extends Error {
  constructor(message:string, public status:number) {super(message); this.name = "AdminApiError";}
}
export async function adminRequest<T>(request:ApiRequest,path:string,method="GET",body?:unknown):Promise<T>{
  try{return await request<T>("/api/admin/"+path,{method,...(body!==undefined?{body:JSON.stringify(body)}:{})});}
  catch(e){throw new AdminApiError(e instanceof Error?e.message:"Nie udało się wykonać operacji.",e instanceof ApiError?e.status:0);}
}
export async function loadOperationsData(request:ApiRequest, capabilities:string[] = []):Promise<OperationsData> {
  // Routes a role cannot read are skipped instead of failing the whole dashboard.
  const optional = async <T,>(path:string, allowed:boolean):Promise<T[]> => allowed ? adminRequest<T[]>(request, path) : [];
  const [orders, inventory, batches, tasks, activity, movements] = await Promise.all([
    adminRequest<Order[]>(request, "orders"), adminRequest<Variant[]>(request, "inventory"),
    adminRequest<Batch[]>(request, "transfers"), adminRequest<Task[]>(request, "production"),
    optional<ActivityEvent>("activity", capabilities.includes("audit")), adminRequest<Movement[]>(request, "stock-events"),
  ]);
  if (![orders, inventory, batches, tasks, activity, movements].every(Array.isArray)) throw new AdminApiError("Serwer zwrócił nieprawidłowe dane panelu.", 200);
  return {orders, inventory, batches, tasks, activity, movements};
}
export function parseOrderLines(items:string | OrderLine[]):OrderLine[] {
  try {const result = typeof items === "string" ? JSON.parse(items) : items; return Array.isArray(result) ? result.filter(line => line && typeof line.sku === "string" && Number.isInteger(line.qty) && line.qty > 0) : [];} catch {return [];}
}
function exportCsv(filename:string, headers:string[], rows:(string | number)[][]) {
  const cell = (value:string | number) => {
    let text = String(value);
    if (typeof value === "string" && /^[=+\-@\t\r]/.test(text)) text = "'" + text;
    return '"' + text.replaceAll('"', '""') + '"';
  };
  const csv = [headers, ...rows].map(row => row.map(cell).join(";")).join("\r\n");
  const url = URL.createObjectURL(new Blob(["\uFEFF" + csv], {type:"text/csv;charset=utf-8"}));
  const link = document.createElement("a"); link.href = url; link.download = filename; link.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
export function StatusBadge({status}:{status:string}) {return <span className={"ops-pill " + status}>{statusText[status] || status}</span>;}
function ScrollTable({children}:{children:ReactNode}) {return <div className="ops-scroll">{children}</div>;}
function Dialog({titleId, onClose, children, wide = false}:{titleId:string; onClose:() => void; children:ReactNode; wide?:boolean}) {
  const ref = useRef<HTMLDivElement>(null);
  const closeRef = useRef(onClose); closeRef.current = onClose;
  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null;
    const overflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    ref.current?.querySelector<HTMLButtonElement>("button")?.focus();
    const onKey = (event:KeyboardEvent) => {
      if (event.key === "Escape") {event.preventDefault(); closeRef.current();}
      if (event.key !== "Tab" || !ref.current) return;
      const controls = Array.from(ref.current.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled), select:not(:disabled), textarea:not(:disabled), a[href], [tabindex="0"]')).filter(element => element.getClientRects().length > 0);
      const first = controls[0], last = controls[controls.length - 1];
      if (!first) {event.preventDefault(); ref.current.focus();}
      else if (event.shiftKey && document.activeElement === first) {event.preventDefault(); last.focus();}
      else if (!event.shiftKey && document.activeElement === last) {event.preventDefault(); first.focus();}
    };
    document.addEventListener("keydown", onKey);
    return () => {document.removeEventListener("keydown", onKey); document.body.style.overflow = overflow; previous?.focus();};
  }, []);
  return <div className="ops-overlay" onMouseDown={event => {if (event.target === event.currentTarget) onClose();}}><div ref={ref} role="dialog" aria-modal="true" aria-labelledby={titleId} tabIndex={-1} className={"ops-modal" + (wide ? " ops-modal-wide" : "")}><button className="ops-close" type="button" aria-label="Zamknij okno" onClick={onClose}><X size={20}/></button>{children}</div></div>;
}

type Props = {request:ApiRequest; activeTab:OperationsTab; data:OperationsData; loading:boolean; onRefresh:() => Promise<boolean>; onAuthError:() => void; requestedOrderId:number | null; onOrderOpened:() => void};
export default function Operations({request, activeTab, data, loading, onRefresh, onAuthError, requestedOrderId, onOrderOpened}:Props) {
  const {orders, inventory, batches, tasks, activity, movements} = data;
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [search, setSearch] = useState("");
  const params=useSearchParams();const router=useRouter();
  const [orderScope,setOrderScope]=useState("active");
  const [statusFilter, setStatusFilter] = useState("");
  useEffect(()=>{const scope=params?.get("lista")||"active";setOrderScope(["active","payment","closed","all"].includes(scope)?scope:"active");setStatusFilter("");},[params]);
  const [lowOnly, setLowOnly] = useState(false);
  const [taskFilter, setTaskFilter] = useState("active");
  const [order, setOrder] = useState<OrderDetail | null>(null);
  const [openingOrder, setOpeningOrder] = useState(false);
  useEffect(()=>{if(activeTab==="orders"&&!params?.get("zamowienie"))setOrder(null);},[params,activeTab]);
  const detailRequest = useRef(0);
  const [scanned, setScanned] = useState<Record<string,number>>({});
  const [orderScan, setOrderScan] = useState("");
  const packingForm = useRef<HTMLFormElement>(null), packingQueued = useRef(false);
  useEffect(() => { if (packingQueued.current) { packingQueued.current = false; packingForm.current?.requestSubmit(); } }, [orderScan]);
  const [packingNotice, setPackingNotice] = useState<{text:string; valid:boolean} | null>(null);
  const [stockEdit, setStockEdit] = useState<Variant | null>(null);
  const [delta, setDelta] = useState("");
  const [reason, setReason] = useState("");
  const [batchForm, setBatchForm] = useState({design:"", supplier:"", reference:"", quantity:"", cost:""});
  const [receive, setReceive] = useState<Record<number,string>>({});
  const [prodOrder, setProdOrder] = useState("");
  const [prodLine, setProdLine] = useState("0");
  const [prodBatch, setProdBatch] = useState("");
  const [selectedLabel, setSelectedLabel] = useState(0);
  const [quantity, setQuantity] = useState(6);
  const [labelFormat, setLabelFormat] = useState<"sheet"|"roll">("sheet");
  const [labelQueue, setLabelQueue] = useState<{id:number; qty:number}[]>([]);
  const [saving, setSaving] = useState(false);
  const [labelScan, setLabelScan] = useState("");
  const [scanResult, setScanResult] = useState<Variant | null>(null);
  const [labelScanError, setLabelScanError] = useState("");
  const [paymentNote, setPaymentNote] = useState("");
  const [refundAmount, setRefundAmount] = useState("");
  const [shipment, setShipment] = useState({carrier:"DPD", tracking_number:""});
  const [cancelReason, setCancelReason] = useState("");
  const [newReturn, setNewReturn] = useState<{kind:"zwrot"|"reklamacja"; reason:string; description:string; qty:Record<number,number>} | null>(null);
  const [decision, setDecision] = useState<StaffReturn | null>(null);
  useEffect(() => {setSearch(""); setError(""); setSuccess(""); setOrder(null); setStockEdit(null); setOpeningOrder(false); detailRequest.current += 1;}, [activeTab]);
  const handleError = (exception:unknown) => {
    if (exception instanceof AdminApiError && exception.status===401) {onAuthError(); return;}
    setError(exception instanceof Error ? exception.message : "Nie udało się wykonać operacji.");
  };
  const mutate = async (path:string, method:string, body:unknown, message:string) => {
    setSaving(true); setError(""); setSuccess("");
    try {await adminRequest(request, path, method, body); setSuccess(message); await onRefresh(); return true;}
    catch (exception) {handleError(exception); return false;}
    finally {setSaving(false);}
  };
  const showOrder = async (id:number, resetScans = true) => {
    const requestId = ++detailRequest.current;
    setOpeningOrder(true); setError("");
    if (resetScans) {setOrder(null); setScanned({}); setOrderScan(""); setPackingNotice(null);}
    try {const result = await adminRequest<OrderDetail>(request, "orders/" + id); if (requestId === detailRequest.current) setOrder(result);}
    catch (exception) {if (requestId === detailRequest.current) handleError(exception);}
    finally {if (requestId === detailRequest.current) setOpeningOrder(false);}
  };
  useEffect(() => {
    if (requestedOrderId !== null) {void showOrder(requestedOrderId); onOrderOpened();}
    // The request is consumed once; snapshots and other form state must not reopen it.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [requestedOrderId]);
  const chosen = inventory.find(variant => variant.id === selectedLabel) || inventory[0];
  const productName = (sku:string) => inventory.find(variant => variant.sku === sku || variant.sku.slice(0, -(variant.size.length + 1)) === sku)?.name || sku;
  const printLabel=(line:{personalization?:OrderPrint})=>line.personalization?`${line.personalization.name} · nr ${line.personalization.number}`:"";
  const linesSummary = (value:string) => parseOrderLines(value).map(line => `${line.qty} × ${line.name || productName(line.sku)} / ${line.size || "UNI"}${line.personalization?" · "+printLabel(line):""}`).join(", ") || "Dane pozycji niedostępne";
  const filteredOrders = orders.filter(item => orderInScope(item,orderScope) && (!statusFilter || item.status === statusFilter) && `${item.id} ${orderNumber(item.id)} ${statusText[item.status]} ${item.items} ${item.customer_name || ""} ${item.customer_email || ""} ${item.tracking_number || ""}`.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.created.localeCompare(a.created)||b.id-a.id);
  const filteredVariants = inventory.filter(variant => (!lowOnly || variant.stock <= 2) && `${variant.name} ${variant.sku} ${variant.ean} ${variant.size}`.toLowerCase().includes(search.toLowerCase()));
  const chosenOrder = orders.find(item => String(item.id) === prodOrder);
  const chosenLines = chosenOrder ? parseOrderLines(chosenOrder.items) : [];
  const selectedLine = chosenLines[Number(prodLine)];
  const assignedLine = tasks.some(task => String(task.order_id) === prodOrder && task.line_index === Number(prodLine));
  const selectedBatch = batches.find(batch => String(batch.id) === prodBatch);
  const canAssign = !!selectedLine && !!selectedBatch && !assignedLine && !isClosedOrder(chosenOrder?.status || "") && selectedBatch.available >= selectedLine.qty;
  const visibleTasks = tasks.filter(task => taskFilter === "all" || (taskFilter === "active" ? !isClosedTask(task.status) : task.status === taskFilter));
  const required = useMemo(() => packingRequirements(order?.items || [], inventory), [order?.items, inventory]);
  const unitsRequired = Object.values(required).reduce((sum, count) => sum + count, 0);
  const unitsScanned = Object.entries(required).reduce((sum, [sku, count]) => sum + Math.min(scanned[sku] || 0, count), 0);
  const verifyOrderScan = () => {
    if (!order || isClosedOrder(order.status)) return;
    const result = applyPackingScan(orderScan, inventory, required, scanned);
    setScanned(result.counts); setPackingNotice({text:result.text, valid:result.valid});
    setOrderScan("");
  };
  const verifyLabelScan = () => {
    const variant = resolveVariantCode(labelScan, inventory);
    setScanResult(variant || null); setLabelScanError(variant ? "" : "Nie znaleziono wariantu dla podanego kodu.");
    if (variant) setSelectedLabel(variant.id);
  };
  const exportOrders = () => exportCsv("zastal-zamowienia.csv", ["Zamówienie", "Data", "Tryb", "Klient", "E-mail", "Pozycje", "Status", "Płatność", "Status płatności", "Dostawa", "Przesyłka", "Wartość PLN"], filteredOrders.map(item => [orderNumber(item.id), item.created, item.mode === "live" ? "sprzedaż" : "test", item.customer_name || item.customer?.name || "", item.customer_email || item.customer?.identifier || "", linesSummary(item.items), statusText[item.status] || item.status, paymentMethodText[item.payment_method || ""] || item.payment_method || "", paymentStatusText[item.payment_status || ""] || "", item.shipping_name || item.fulfillment || "", item.tracking_number || "", (item.total / 100).toFixed(2)]));
  const exportInventory = () => exportCsv("zastal-magazyn-wariantow.csv", ["Produkt", "Rozmiar", "SKU", "EAN", "Stan", "Cena PLN"], filteredVariants.map(variant => [variant.name, variant.size, variant.sku, variant.ean, variant.stock, (variant.price / 100).toFixed(2)]));
  const closeOrder = () => {detailRequest.current += 1; setOrder(null); setOpeningOrder(false);const query=new URLSearchParams(params?.toString());query.delete("zamowienie");router.replace(adminPath("orders")+(query.size?"?"+query.toString():""),{scroll:false});};
  const selectOrderScope=(scope:string)=>{setOrderScope(scope);setStatusFilter("");const query=new URLSearchParams(params?.toString());query.delete("zamowienie");if(scope==="active")query.delete("lista");else query.set("lista",scope);router.replace(adminPath("orders")+(query.size?"?"+query.toString():""),{scroll:false});};
  const openOrderLink=(id:number)=>{const query=new URLSearchParams(params?.toString());query.set("zamowienie",String(id));router.push(adminPath("orders")+"?"+query.toString(),{scroll:false});};
  if (activeTab === "dashboard") return null;

  return <div className="ops" aria-busy={loading || saving}>
    {error && <div className="ops-message ops-error" role="alert"><AlertCircle size={18}/><span>{error}</span><button aria-label="Zamknij komunikat" onClick={() => setError("")}><X size={16}/></button></div>}
    {success && <div className="ops-message ops-success" role="status"><CheckCircle2 size={18}/><span>{success}</span><button aria-label="Zamknij komunikat" onClick={() => setSuccess("")}><X size={16}/></button></div>}
    {openingOrder && <p className="ops-loading" role="status">Pobieranie szczegółów zamówienia…</p>}
    {activeTab==="orders"&&<div className="admin-order-scopes" aria-label="Widok zamówień">{[["active","Do realizacji"],["payment","Płatności"],["closed","Zakończone"],["all","Wszystkie"]].map(([scope,label])=><button key={scope} aria-pressed={orderScope===scope} className={orderScope===scope?"selected":""} onClick={()=>selectOrderScope(scope)}>{label}<span>{orders.filter(order=>orderInScope(order,scope)).length}</span></button>)}</div>}
    {(activeTab === "orders" || activeTab === "inventory") && <div className="ops-toolbar">{activeTab === "inventory" && <ScanButton label="Skanuj EAN" hint="Zeskanuj EAN, aby znaleźć wariant w magazynie" onScan={code => setSearch(code)}/>}<label className="ops-search"><Search size={18}/><input aria-label={activeTab === "orders" ? "Szukaj zamówień" : "Szukaj wariantów"} value={search} onChange={event => setSearch(event.target.value)} placeholder={activeTab === "orders" ? "Numer, klient, e-mail, produkt, przesyłka lub status" : "Nazwa, rozmiar, SKU lub EAN"}/>{search && <button aria-label="Wyczyść wyszukiwanie" type="button" onClick={() => setSearch("")}><X size={16}/></button>}</label>{activeTab === "orders" ? <select className="ops-filter" aria-label="Filtr statusu zamówienia" value={statusFilter} onChange={event => setStatusFilter(event.target.value)}><option value="">Wszystkie statusy</option>{orderStatuses.map(status => <option key={status} value={status}>{statusText[status]}</option>)}</select> : <label className="ops-checkbox"><input type="checkbox" checked={lowOnly} onChange={event => setLowOnly(event.target.checked)}/>Tylko stany 0–2 szt.</label>}<button className="ops-action" onClick={activeTab === "orders" ? exportOrders : exportInventory} disabled={loading}><ArrowDownToLine size={16}/>Eksport CSV</button></div>}

    {activeTab === "orders" && <section className="ops-panel"><div className="ops-panel-head"><h2>Zamówienia <span>{filteredOrders.length}</span></h2><p>Ostatnie 300 zapisanych zamówień</p></div><ScrollTable><table className="ops-table ops-orders-table"><thead><tr><th>Zamówienie</th><th>Pozycje</th><th>Wartość</th><th>Płatność</th><th>Status</th><th><span className="ops-sr-only">Szczegóły</span></th></tr></thead><tbody>{filteredOrders.map(item => <tr key={item.id}><td><strong>{orderNumber(item.id)}</strong><small>{formatDate(item.created)}{item.mode==="live"?"":" · test"}</small>{item.customer_name&&<small>{item.customer_name}</small>}</td><td>{linesSummary(item.items)}</td><td className="ops-nowrap">{formatMoney(item.total)}</td><td>{item.mode==="live"?<span className={"ops-pill pay-"+(item.payment_status||"unpaid")}>{paymentStatusText[item.payment_status||"unpaid"]}</span>:<span className="ops-muted">—</span>}</td><td><StatusBadge status={item.status}/></td><td><button className="ops-action" aria-label={"Otwórz " + orderNumber(item.id)} onClick={() => openOrderLink(item.id)} disabled={openingOrder}>Szczegóły<ArrowRight size={15}/></button></td></tr>)}</tbody></table></ScrollTable>{!filteredOrders.length && <p className="ops-empty">{search || statusFilter ? "Brak zamówień spełniających kryteria." : "Brak zamówień w tym widoku."}</p>}</section>}

    {activeTab === "inventory" && <section className="ops-panel"><div className="ops-panel-head"><h2>Warianty produktów <span>{filteredVariants.length}</span></h2><p>Korekty z uzasadnieniem trafiają do historii</p></div><ScrollTable><table className="ops-table"><thead><tr><th>Produkt</th><th>Rozmiar i SKU</th><th>EAN</th><th>Stan</th><th><span className="ops-sr-only">Korekta</span></th></tr></thead><tbody>{filteredVariants.map(variant => <tr key={variant.id}><td><strong>{variant.name}</strong><small>{variant.category}</small></td><td><b className="ops-size">{variant.size}</b><small className="ops-monospaced">{variant.sku}</small></td><td className="ops-monospaced">{variant.ean}</td><td><span className={"ops-quantity" + (variant.stock <= 2 ? " warning" : "")}>{variant.stock} szt.</span></td><td><button className="ops-action" onClick={() => {setStockEdit(variant); setError(""); setDelta(""); setReason("");}}>Korekta<Plus size={15}/></button></td></tr>)}</tbody></table></ScrollTable>{!filteredVariants.length && <p className="ops-empty">Brak wariantów spełniających kryteria.</p>}</section>}

    {activeTab === "transfers" && <div className="ops-two"><section className="ops-panel"><div className="ops-panel-head"><h2>Zakup gotowych transferów</h2></div><form className="ops-form" onSubmit={async event => {event.preventDefault(); const ok = await mutate("transfers", "POST", {design:batchForm.design.trim(), supplier:batchForm.supplier.trim(), reference:batchForm.reference.trim(), quantity:Number(batchForm.quantity), cost_unit:Math.round(Number(batchForm.cost) * 100)}, "Zapisano zakup transferów. Partia oczekuje na przyjęcie."); if (ok) setBatchForm({design:"", supplier:"", reference:"", quantity:"", cost:""});}}><label>Nazwa wzoru<input required maxLength={100} value={batchForm.design} onChange={event => setBatchForm({...batchForm, design:event.target.value})} placeholder="Np. Zastal Classic — przód"/></label><label>Dostawca<input required maxLength={100} value={batchForm.supplier} onChange={event => setBatchForm({...batchForm, supplier:event.target.value})} placeholder="Nazwa dostawcy"/></label><label>Numer zamówienia u dostawcy <span className="ops-optional">(opcjonalnie)</span><input maxLength={80} value={batchForm.reference} onChange={event => setBatchForm({...batchForm, reference:event.target.value})} placeholder="Numer referencyjny"/></label><div className="ops-form-cols"><label>Liczba transferów<input type="number" required min={1} max={100000} step={1} value={batchForm.quantity} onChange={event => setBatchForm({...batchForm, quantity:event.target.value})}/></label><label>Koszt 1 szt. (zł)<input type="number" min={0} step="0.01" value={batchForm.cost} onChange={event => setBatchForm({...batchForm, cost:event.target.value})} placeholder="0,00"/></label></div><button className="ops-primary" disabled={saving || loading}>Zapisz zakup<Plus size={17}/></button></form><p className="ops-info">DTF to gotowe transfery kupowane od zewnętrznego dostawcy i nanoszone na odzież. Zakup i fizyczne przyjęcie dostawy zapisuje się osobno.</p></section><section className="ops-panel"><div className="ops-panel-head"><h2>Partie i przyjęcia <span>{batches.length}</span></h2><p>{batches.reduce((sum, batch) => sum + batch.available, 0)} szt. dostępnych</p></div><div className="ops-batch-list">{batches.map(batch => <article className="ops-batch" key={batch.id}><div className="ops-batch-title"><span className="ops-batch-id">#{String(batch.id).padStart(3, "0")}</span><div><h3>{batch.design}</h3><p>{batch.supplier}{batch.reference ? " · " + batch.reference : ""}</p><small>{formatDate(batch.created)} · {formatMoney(batch.cost_unit)} / szt.</small></div></div><dl className="ops-batch-counts"><div><dt>Zamówione</dt><dd>{batch.ordered}</dd></div><div><dt>Przyjęte</dt><dd>{batch.received}</dd></div><div><dt>Dostępne</dt><dd>{batch.available}</dd></div></dl>{batch.received < batch.ordered ? <form className="ops-receive" onSubmit={async event => {event.preventDefault(); const ok = await mutate("transfers/" + batch.id + "/receive", "PATCH", {quantity:Number(receive[batch.id])}, "Zapisano przyjęcie transferów do magazynu."); if (ok) setReceive(previous => ({...previous, [batch.id]:""}));}}><label><span>Przyjmij do {batch.ordered - batch.received} szt.</span><input aria-label={"Liczba przyjmowanych transferów z partii " + batch.id} type="number" required min={1} max={batch.ordered - batch.received} step={1} value={receive[batch.id] || ""} onChange={event => setReceive(previous => ({...previous, [batch.id]:event.target.value}))} placeholder="Liczba sztuk"/></label><button className="ops-action" disabled={saving || loading}><ArrowDownToLine size={16}/>Przyjmij</button></form> : <p className="ops-received"><CheckCircle2 size={15}/>Dostawa przyjęta w całości</p>}</article>)}{!batches.length && <p className="ops-empty">Nie zapisano jeszcze zakupów transferów.</p>}</div></section></div>}

    {activeTab === "production" && <div className="ops-two"><section className="ops-panel"><div className="ops-panel-head"><h2>Nowe zlecenie nanoszenia</h2></div><form className="ops-form" onSubmit={async event => {event.preventDefault(); if (!canAssign) return; const ok = await mutate("production", "POST", {order_id:Number(prodOrder), line_index:Number(prodLine), batch_id:Number(prodBatch)}, "Zlecenie utworzone. Transfery zostały zarezerwowane."); if (ok) {setProdOrder(""); setProdBatch(""); setProdLine("0");}}}><label>Zamówienie<select required value={prodOrder} onChange={event => {const next = orders.find(item => String(item.id) === event.target.value); const firstFree = next ? parseOrderLines(next.items).findIndex((_, index) => !tasks.some(task => task.order_id === next.id && task.line_index === index)) : 0; setProdOrder(event.target.value); setProdLine(String(Math.max(0, firstFree))); setProdBatch("");}}><option value="">Wybierz zamówienie</option>{orders.filter(item => !isClosedOrder(item.status)).map(item => <option key={item.id} value={item.id}>{orderNumber(item.id)} · {statusText[item.status] || item.status}</option>)}</select></label><label>Pozycja zamówienia<select value={prodLine} disabled={!chosenLines.length} onChange={event => {setProdLine(event.target.value); setProdBatch("");}}>{!chosenLines.length && <option value="0">Najpierw wybierz zamówienie</option>}{chosenLines.map((line, index) => <option key={index} value={index} disabled={tasks.some(task => task.order_id === chosenOrder?.id && task.line_index === index)}>{index + 1}. {line.name || productName(line.sku)} / {line.size || "UNI"} × {line.qty}{line.personalization?" · "+printLabel(line):""}{tasks.some(task => task.order_id === chosenOrder?.id && task.line_index === index) ? " — zlecenie istnieje" : ""}</option>)}</select></label><label>Partia gotowych transferów<select required value={prodBatch} onChange={event => setProdBatch(event.target.value)}><option value="">Wybierz partię</option>{batches.filter(batch => batch.available > 0).map(batch => <option key={batch.id} value={batch.id} disabled={!!selectedLine && batch.available < selectedLine.qty}>#{batch.id} {batch.design} · {batch.available} szt. dostępnych</option>)}</select></label>{assignedLine && <p className="ops-form-note">Ta pozycja ma już zlecenie nanoszenia.</p>}<button className="ops-primary" disabled={saving || loading || !canAssign}>Przydziel transfery<ArrowRight size={17}/></button></form><p className="ops-info">Zlecenie rezerwuje po jednym transferze na każdą sztukę z wybranej pozycji zamówienia. Etapy nanoszenia i kontroli zapisują się w historii.</p></section><section className="ops-panel"><div className="ops-panel-head ops-queue-head"><h2>Kolejka nanoszenia <span>{visibleTasks.length}</span></h2><select className="ops-filter" aria-label="Filtr kolejki nanoszenia" value={taskFilter} onChange={event => setTaskFilter(event.target.value)}><option value="active">Aktywne zlecenia</option><option value="all">Wszystkie zlecenia</option>{productionStatuses.map(status => <option key={status} value={status}>{statusText[status]}</option>)}</select></div><div className="ops-tasks">{visibleTasks.map(task => <article className="ops-task" key={task.id}><div className="ops-task-heading"><strong>DTF-{String(task.id).padStart(4, "0")}</strong><StatusBadge status={task.status}/></div><h3>{task.design}</h3>{task.product_name&&<p>{task.product_name} / {task.size} × {task.qty}</p>}{task.personalization&&<p className="ops-print-label">Nadruk: {printLabel(task)}</p>}<button className="ops-text-link" onClick={() => void showOrder(task.order_id)}>{orderNumber(task.order_id)} · pozycja {task.line_index + 1}<ArrowRight size={14}/></button><p>{task.supplier}{task.reference ? " · " + task.reference : ""}</p><small>Aktualizacja: {formatDate(task.updated)}</small><label>Etap zlecenia<select value={task.status} disabled={saving || loading || isClosedTask(task.status)} onChange={event => void mutate("production/" + task.id, "PATCH", {status:event.target.value}, "Zapisano etap nanoszenia.")}>{productionStatuses.map(status => <option key={status} value={status}>{statusText[status]}</option>)}</select></label></article>)}{!visibleTasks.length && <p className="ops-empty">Brak zleceń w wybranym etapie.</p>}</div></section></div>}

    {activeTab === "labels" && <div className="ops-two"><section className="ops-panel"><div className="ops-panel-head"><h2>Druk etykiet wariantów</h2></div><div className="ops-form"><label>Produkt i rozmiar<select value={chosen?.id || ""} onChange={event => setSelectedLabel(Number(event.target.value))}>{!inventory.length && <option value="">Brak wariantów</option>}{inventory.map(variant => <option key={variant.id} value={variant.id}>{variant.name} / {variant.size} · {variant.sku}</option>)}</select></label><label>Liczba etykiet<input type="number" min={1} max={48} step={1} value={quantity} onChange={event => setQuantity(Math.max(1, Math.min(48, Math.trunc(Number(event.target.value)) || 1)))}/></label><label>Format wydruku<select value={labelFormat} onChange={event => setLabelFormat(event.target.value as "sheet"|"roll")}><option value="sheet">Arkusz A4, etykiety 60 × 40 mm</option><option value="roll">Drukarka etykiet, rolka 50 × 30 mm</option></select></label><button className="ops-primary" onClick={() => window.print()} disabled={(!chosen && !labelQueue.length) || loading}><Printer size={17}/>Drukuj {labelQueue.length ? labelQueue.reduce((n, item) => n + item.qty, 0) : quantity} etykiet</button></div><div className="ops-label-queue"><div className="ops-label-queue-actions"><button className="ops-action" disabled={!chosen} onClick={() => chosen && setLabelQueue(queue => {const rest = queue.filter(item => item.id !== chosen.id); return [...rest, {id:chosen.id, qty:quantity}];})}><Plus size={15}/>Dodaj do kolejki</button><button className="ops-action" disabled={!chosen} onClick={() => chosen && setLabelQueue(queue => {const siblings = inventory.filter(variant => variant.product_id === chosen.product_id); const rest = queue.filter(item => !siblings.some(v => v.id === item.id)); return [...rest, ...siblings.map(variant => ({id:variant.id, qty:Math.max(1, Math.min(48, variant.stock || 1))}))];})}>Wszystkie rozmiary według stanu</button>{labelQueue.length > 0 && <button className="ops-action" onClick={() => setLabelQueue([])}>Wyczyść</button>}</div>{labelQueue.length > 0 && <ul className="ops-label-queue-list">{labelQueue.map(item => {const variant = inventory.find(v => v.id === item.id); return variant ? <li key={item.id}><span>{variant.name} / {variant.size}</span><input type="number" min={1} max={200} value={item.qty} aria-label={"Liczba etykiet: " + variant.name + " " + variant.size} onChange={event => setLabelQueue(queue => queue.map(entry => entry.id === item.id ? {...entry, qty:Math.max(1, Math.min(200, Math.trunc(Number(event.target.value)) || 1))} : entry))}/><button type="button" className="admin-text-link" onClick={() => setLabelQueue(queue => queue.filter(entry => entry.id !== item.id))}>Usuń</button></li> : null;})}</ul>}<p className="ops-info">{labelFormat === "roll" ? "Rolka: każda etykieta to osobna strona 50 × 30 mm. W oknie drukowania wybierz drukarkę etykiet, format papieru 50 × 30 mm i margines 0." : "Arkusz A4: etykiety układają się po kilka w rzędzie; w oknie drukowania wybierz skalę 100%."}</p></div><form className="ops-scan" onSubmit={event => {event.preventDefault(); verifyLabelScan();}}><label>Sprawdź kod EAN, QR lub SKU<input value={labelScan} onChange={event => setLabelScan(event.target.value)} placeholder="Zeskanuj kod lub wpisz SKU" autoComplete="off"/></label><button className="ops-action" disabled={!inventory.length}><ScanLine size={17}/>Sprawdź</button>{scanResult && <p className="ops-scan-feedback" role="status"><CheckCircle2 size={16}/>{scanResult.name}, rozmiar {scanResult.size} · {scanResult.stock} szt.</p>}{labelScanError && <p className="ops-scan-error" role="alert">{labelScanError}</p>}</form><p className="ops-info">EAN-13 z prefiksem 200 służy do obiegu wewnętrznego. Nie jest globalnym numerem GTIN zarejestrowanym w GS1. Kod QR zawiera SKU i EAN tego samego wariantu.</p></section><section className="ops-panel"><div className="ops-panel-head"><h2>Podgląd etykiety</h2><p>{labelFormat === "roll" ? "50 × 30 mm · rolka" : "60 × 40 mm · arkusz A4"}</p></div><div className="ops-label-stage">{chosen ? <Label variant={chosen} compact={labelFormat === "roll"}/> : <p className="ops-empty">Brak danych wariantów do wydruku.</p>}</div>{chosen && <div className="ops-label-detail"><strong>{chosen.name} / {chosen.size}</strong><span>{chosen.sku}</span><span>EAN {chosen.ean}</span></div>}</section>{labelFormat === "roll" && <style>{"@media print{@page{size:50mm 30mm;margin:0}.ops-print-area{width:50mm!important;gap:0!important;display:block!important}.ops-printed-label{break-after:page!important;page-break-after:always!important;outline:none!important;margin:0!important}}"}</style>}<div className={"ops-print-area" + (labelFormat === "roll" ? " roll" : "")}>{(labelQueue.length ? labelQueue.flatMap(item => {const variant = inventory.find(v => v.id === item.id); return variant ? Array.from({length:item.qty}, (_, index) => ({variant, key:item.id + "-" + index})) : [];}) : chosen ? Array.from({length:quantity}, (_, index) => ({variant:chosen, key:"single-" + index})) : []).map(entry => <Label key={entry.key} variant={entry.variant} compact={labelFormat === "roll"}/>)}</div></div>}

    {activeTab === "audit" && <><div className="ops-audit-toolbar"><p>Ostatnie 80 działań i 100 ruchów magazynowych</p><button className="ops-action" onClick={() => exportCsv("zastal-historia.csv", ["Typ", "Obiekt", "Opis", "Data"], [...activity.map(event => [activityText[event.kind] || event.kind, event.object_id, event.note, event.created]), ...movements.map(movement => ["Ruch magazynowy", movement.sku, `${movement.delta > 0 ? "+" : ""}${movement.delta} szt. · ${movement.reason}`, movement.created])])}><ArrowDownToLine size={16}/>Eksport CSV</button></div><div className="ops-two"><section className="ops-panel"><div className="ops-panel-head"><h2>Historia działań <span>{activity.length}</span></h2></div><div className="ops-log">{activity.map(event => <article key={event.id}><Clock3 size={17}/><div><h3>{activityText[event.kind] || event.kind} <span>#{event.object_id}</span></h3><p>{event.note}</p><small>{formatDate(event.created)}</small></div></article>)}{!activity.length && <p className="ops-empty">Brak zapisanych działań.</p>}</div></section><section className="ops-panel"><div className="ops-panel-head"><h2>Ruchy magazynowe <span>{movements.length}</span></h2></div><div className="ops-log">{movements.map(movement => <article key={movement.id}><Warehouse size={17}/><div><h3 className="ops-monospaced">{movement.sku}<span className={movement.delta < 0 ? "ops-negative" : "ops-positive"}>{movement.delta > 0 ? "+" : ""}{movement.delta} szt.</span></h3><p>{movement.reason}</p><small>{formatDate(movement.created)} · {sourceText[movement.source] || movement.source}</small></div></article>)}{!movements.length && <p className="ops-empty">Brak ruchów magazynowych.</p>}</div></section></div></>}

    {decision && <ReturnDecision item={decision} onDone={async () => {await onRefresh(); if (order) await showOrder(order.id, false);}} onClose={() => setDecision(null)}/>}
    {stockEdit && <Dialog titleId="stock-dialog-title" onClose={() => setStockEdit(null)}><p className="ops-dialog-eyebrow">Magazyn wariantów</p><h2 id="stock-dialog-title">Korekta stanu</h2><h3>{stockEdit.name} / {stockEdit.size}</h3><p className="ops-dialog-description">{stockEdit.sku} · aktualnie {stockEdit.stock} szt.</p><form className="ops-form ops-modal-form" onSubmit={async event => {event.preventDefault(); const value = Number(delta); if (!Number.isInteger(value) || !value || stockEdit.stock + value < 0) {setError("Podaj zmianę różną od zera. Stan po korekcie nie może być ujemny."); return;} const ok = await mutate("inventory/" + stockEdit.id, "PATCH", {delta:value, reason:reason.trim()}, "Zapisano korektę i ruch magazynowy."); if (ok) setStockEdit(null);}}><label>Zmiana liczby sztuk<input type="number" required min={Math.max(-5000, -stockEdit.stock)} max={5000} step={1} value={delta} onChange={event => setDelta(event.target.value)} placeholder="Np. 10 lub -2"/><span className="ops-field-hint">Stan po korekcie: {stockEdit.stock + (Number(delta) || 0)} szt.</span></label><label>Powód korekty<input required minLength={3} maxLength={150} value={reason} onChange={event => setReason(event.target.value)} placeholder="Dostawa, remanent, uszkodzenie…"/></label>{error && <p className="ops-form-error" role="alert">{error}</p>}<button className="ops-primary" disabled={saving || loading || !Number(delta)}>Zapisz korektę<CheckCircle2 size={17}/></button></form></Dialog>}

    {order && <Dialog titleId="order-dialog-title" onClose={closeOrder} wide><p className="ops-dialog-eyebrow">Szczegóły zamówienia</p><h2 id="order-dialog-title">{orderNumber(order.id)}</h2><p className="ops-dialog-description">{formatDate(order.created)} · {formatMoney(order.total)}</p>{order.customer&&<p className="ops-order-customer">Klient: <strong>{order.customer.name}</strong> · {order.customer.identifier}</p>}<div className="ops-order-status"><label htmlFor="order-status-select">Status realizacji</label><select id="order-status-select" value={order.status} disabled={saving || openingOrder || isClosedOrder(order.status)} onChange={async event => {const id = order.id; const pendingDetail = detailRequest.current; const ok = await mutate("orders/" + id, "PATCH", {status:event.target.value}, "Zmiana statusu zapisana w historii."); if (ok && pendingDetail === detailRequest.current) await showOrder(id, false);}}>{orderStatuses.map(status => <option key={status} value={status} disabled={status !== order.status && ["spakowane", "wyslane", "wyslane_demo", "wydane", "oplacone", "zwrot"].includes(status)}>{statusText[status]}{status !== order.status && ["spakowane", "wyslane", "wyslane_demo", "wydane", "oplacone", "zwrot"].includes(status) ? " (przez Realizację / Płatność / Wysyłkę)" : ""}</option>)}</select></div>{error && <p className="ops-form-error" role="alert">{error}</p>}<h3 className="ops-detail-title">Pozycje zamówienia</h3><div className="ops-order-lines">{order.items.map((line, index) => <div className="ops-order-line" key={index}><div><strong>{line.name || productName(line.sku)}</strong><small>{lineVariantSku(line, inventory)} / {line.size || "UNI"}</small>{line.personalization&&<small className="ops-print-label">Nadruk: {printLabel(line)}{line.decoration_method?" · "+(({dtf:"DTF",haft:"haft",haft_3d:"haft 3D",sitodruk:"sitodruk",inne:"inna metoda"} as Record<string,string>)[line.decoration_method]||line.decoration_method):""}{line.personalization_fee?" · dopłata "+formatMoney(line.personalization_fee):" · w cenie"}</small>}{line.preorder&&<small className="ops-muted">Przedsprzedaż: {line.preorder.note}</small>}</div><span>{line.qty} × {formatMoney(line.unit_price)}</span></div>)}</div>{order.fulfillment && !order.details && <p className="ops-order-delivery">Dostawa: {({odbior:"Odbiór osobisty", paczkomat:"Paczkomat", kurier:"Kurier"} as Record<string,string>)[order.fulfillment] || order.fulfillment}{typeof order.shipping_fee === "number" ? " · " + formatMoney(order.shipping_fee) : ""} (zamówienie testowe)</p>}
    {order.details && (() => {const d = order.details; const live = d.mode === "live"; const paid = d.payment_status === "paid"; const kind = d.shipping_kind; return <section className="ops-order-commerce"><div className="ops-commerce-grid"><div><h3 className="ops-detail-title">Klient i dostawa</h3><p><strong>{d.customer_name || "—"}</strong><br/>{d.customer_email}{d.customer_phone ? <><br/>{d.customer_phone}</> : null}</p><p><strong>{d.shipping_name || order.fulfillment}</strong>{typeof order.shipping_fee === "number" ? " · " + (order.shipping_fee ? formatMoney(order.shipping_fee) : "bezpłatnie") : ""}<br/>{kind === "pickup" ? "Odbiór osobisty" : kind === "locker" ? "Automat: " + d.locker_code : <>{d.address.line1}{d.address.line2 ? ", " + d.address.line2 : ""}<br/>{d.address.postal_code} {d.address.city}</>}</p>{d.invoice?.requested && <p><strong>Faktura:</strong> {d.invoice.company}, NIP {d.invoice.tax_id}<br/>{d.invoice.address}</p>}{!live && <p className="ops-muted">Zamówienie testowe — bez płatności i wysyłki.</p>}</div>
      {live && <div><h3 className="ops-detail-title">Płatność</h3><p><strong>{paymentMethodText[d.payment_method] || d.payment_method}</strong> · <span className={"ops-pill pay-" + d.payment_status}>{paymentStatusText[d.payment_status] || d.payment_status}</span>{d.paid_at && <small> · {formatDate(d.paid_at)}</small>}</p>{d.payment_note && <p className="ops-muted">{d.payment_note}</p>}{order.transfer && !paid && <p className="ops-muted">Oczekiwany tytuł: <span className="ops-monospaced">{order.transfer.title}</span> · {formatMoney(order.transfer.amount)}</p>}{(order.payments || []).map(payment => <p key={payment.id} className="ops-muted">PayU {payment.ext_order_id} · {payment.status} · {formatMoney(payment.amount)} · {payment.environment}{payment.refunds.map(refund => <span key={refund.id}><br/>zwrot {formatMoney(refund.amount)} · {refund.status}{refund.reason ? " · " + refund.reason : ""}</span>)}</p>)}
        <div className="ops-payment-actions">{!paid && d.payment_method !== "payu" && order.status !== "anulowane" && <button className="ops-primary" disabled={saving} onClick={async () => {const id = order.id; const ok = await mutate("orders/" + id + "/payment", "POST", {action:"confirm", note:paymentNote.trim()}, "Wpłata potwierdzona. Zamówienie trafiło do realizacji."); if (ok) {setPaymentNote(""); await showOrder(id, false);}}}><CheckCircle2 size={16}/>Potwierdź wpłatę</button>}{(paid || d.payment_status === "partially_refunded") && <form className="ops-refund" onSubmit={async event => {event.preventDefault(); const amount = Math.round(Number(refundAmount.replace(",", ".")) * 100); if (!Number.isInteger(amount) || amount < 1) {setError("Podaj kwotę zwrotu w PLN."); return;} if (!window.confirm(`Zlecić zwrot ${formatMoney(amount)} dla ${orderNumber(order.id)}?`)) return; const id = order.id; const ok = await mutate("orders/" + id + "/payment", "POST", {action:"refund", amount, note:paymentNote.trim()}, d.payment_method === "payu" ? "Zwrot zlecony w PayU. Status zmieni się po potwierdzeniu operatora." : "Zwrot zarejestrowany."); if (ok) {setRefundAmount(""); setPaymentNote(""); await showOrder(id, false);}}}><input aria-label="Kwota zwrotu w PLN" inputMode="decimal" placeholder={(order.total / 100).toFixed(2)} value={refundAmount} onChange={event => setRefundAmount(event.target.value)}/><button className="ops-action" disabled={saving}>{d.payment_method === "payu" ? "Zleć zwrot PayU" : "Zarejestruj zwrot"}</button></form>}<input aria-label="Notatka do płatności" placeholder="Notatka (np. data wyciągu)" maxLength={200} value={paymentNote} onChange={event => setPaymentNote(event.target.value)}/></div></div>}
      {live && kind !== "pickup" && <div><h3 className="ops-detail-title">Wysyłka</h3>{d.tracking_number ? <p><strong>{d.carrier}</strong> · <span className="ops-monospaced">{d.tracking_number}</span>{d.shipped_at && <small> · {formatDate(d.shipped_at)}</small>}{d.tracking_url && <><br/><a href={d.tracking_url} target="_blank" rel="noreferrer" className="ops-text-link">Śledzenie przesyłki</a></>}</p> : order.status === "spakowane" ? <form className="ops-shipment" onSubmit={async event => {event.preventDefault(); const id = order.id; const ok = await mutate("orders/" + id + "/shipment", "POST", {carrier:shipment.carrier.trim(), tracking_number:shipment.tracking_number.trim()}, "Przesyłka nadana. Klient otrzyma e-mail z numerem."); if (ok) {setShipment({carrier:"", tracking_number:""}); await showOrder(id, false);}}}><input aria-label="Przewoźnik" placeholder="Przewoźnik" required maxLength={80} value={shipment.carrier} onChange={event => setShipment({...shipment, carrier:event.target.value})}/><input aria-label="Numer przesyłki" placeholder="Numer przesyłki" required maxLength={64} value={shipment.tracking_number} onChange={event => setShipment({...shipment, tracking_number:event.target.value})}/><button className="ops-primary" disabled={saving || (!paid && d.payment_method !== "pickup")}>Nadaj przesyłkę</button>{!paid && d.payment_method !== "pickup" && <small className="ops-muted">Wysyłka dopiero po opłaceniu.</small>}</form> : <p className="ops-muted">Numer przesyłki wpiszesz po spakowaniu zamówienia w Realizacji.</p>}</div>}</div></section>;})()}<section className="ops-packing"><div className="ops-packing-heading"><h3>Kontrola do pakowania</h3><span className={unitsRequired > 0 && unitsScanned === unitsRequired ? "ops-packed" : ""}>{unitsScanned}/{unitsRequired} szt.</span></div><p>Skan potwierdza sztukę i rozmiar. Nazwisko oraz numer na koszulce sprawdź według pozycji zamówienia. Wynik kontroli jest przechowywany w tej sesji okna.</p><div className="staff-scan-camera"><ScanButton onScan={code => { packingQueued.current = true; setOrderScan(code); }} hint="Zeskanuj EAN lub QR pakowanej sztuki"/></div><form ref={packingForm} className="ops-packing-scan" onSubmit={event => {event.preventDefault(); verifyOrderScan();}}><input aria-label="Kod wariantu do pakowania" value={orderScan} onChange={event => setOrderScan(event.target.value)} placeholder="EAN, QR lub SKU" autoComplete="off"/><button className="ops-action" disabled={!orderScan.trim() || isClosedOrder(order.status)}><ScanLine size={17}/>Potwierdź sztukę</button></form>{packingNotice && <p className={packingNotice.valid ? "ops-scan-feedback" : "ops-scan-error"} role="status">{packingNotice.valid ? <CheckCircle2 size={16}/> : <AlertCircle size={16}/>} {packingNotice.text}</p>}<ul className="ops-packing-lines">{Object.entries(required).map(([sku, count]) => <li key={sku}><span className="ops-monospaced">{sku}</span><span className={(scanned[sku] || 0) >= count ? "ops-packed" : ""}>{Math.min(scanned[sku] || 0, count)}/{count} szt.</span></li>)}</ul>{unitsScanned > 0 && <button type="button" className="ops-text-link" onClick={() => {setScanned({}); setPackingNotice(null);}}>Wyzeruj kontrolę</button>}</section>{(order.returns || []).length > 0 && <><h3 className="ops-detail-title">Zwroty i reklamacje</h3><div className="ops-detail-production">{order.returns!.map(item => <div key={item.id}><span>{item.kind === "zwrot" ? "Zwrot" : "Reklamacja"} #{item.id} · {item.reason_label} · {formatMoney(item.refund_amount)}</span><button className="ops-action" onClick={() => setDecision(item)}>{["odrzucony", "rozliczony"].includes(item.status) ? "Podgląd" : "Decyzja"}</button></div>)}</div></>}
    {["wydane", "wyslane", "spakowane", "oplacone", "do_kompletacji", "nanoszenie_dtf", "kontrola_jakosci", "potwierdzone"].includes(order.status) && <div className="ops-return-create">{newReturn ? <form className="ops-form ops-modal-form" onSubmit={async event => {event.preventDefault(); const items = Object.entries(newReturn.qty).filter(([, value]) => value > 0).map(([index, value]) => ({line_index:Number(index), qty:value})); if (!items.length) {setError("Zaznacz pozycje zwrotu."); return;} const id = order.id; const ok = await mutate("returns", "POST", {order_id:id, kind:newReturn.kind, reason:newReturn.reason, description:newReturn.description.trim(), items}, "Zgłoszenie zapisane. Decyzję i zwrot środków zapiszesz w zakładce Zwroty."); if (ok) {setNewReturn(null); await showOrder(id, false);}}}><h3 className="ops-detail-title">Nowe zgłoszenie (przy ladzie / telefonicznie)</h3><div className="ops-form-cols"><label>Rodzaj<select value={newReturn.kind} onChange={event => setNewReturn({...newReturn, kind:event.target.value as "zwrot" | "reklamacja"})}><option value="zwrot">Zwrot</option><option value="reklamacja">Reklamacja</option></select></label><label>Powód<select value={newReturn.reason} onChange={event => setNewReturn({...newReturn, reason:event.target.value})}>{Object.entries({rozmiar:"Zły rozmiar", wada:"Wada produktu", niezgodny:"Niezgodny z zamówieniem", odstapienie:"Odstąpienie od umowy", inny:"Inny"}).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></label></div>{order.items.map((line, index) => <label key={index} className="ops-checkbox"><input type="checkbox" checked={(newReturn.qty[index] || 0) > 0} onChange={event => setNewReturn({...newReturn, qty:{...newReturn.qty, [index]:event.target.checked ? line.qty : 0}})}/>{line.qty} × {line.name || line.sku} / {line.size || "UNI"}</label>)}<label>Opis<input maxLength={1000} value={newReturn.description} onChange={event => setNewReturn({...newReturn, description:event.target.value})}/></label><div className="ops-form-cols"><button className="ops-primary" disabled={saving}>Zapisz zgłoszenie</button><button type="button" className="ops-action" onClick={() => setNewReturn(null)}>Anuluj</button></div></form> : <button className="ops-action" onClick={() => setNewReturn({kind:"zwrot", reason:"rozmiar", description:"", qty:{}})}>Zgłoś zwrot / reklamację dla tego zamówienia</button>}</div>}
    {!isClosedOrder(order.status) && (order.printed_lines || []).length > 0 && <div className="ops-cancel-override"><h3 className="ops-detail-title">Anulowanie po personalizacji</h3><p className="ops-muted">Część sztuk ma już naniesiony nadruk. Zwykłe anulowanie jest zablokowane; menedżer może anulować z odpisem spersonalizowanych sztuk (nie wracają na stan).</p><form className="ops-form-cols" onSubmit={async event => {event.preventDefault(); if (!window.confirm("Anulować zamówienie z odpisem spersonalizowanych sztuk?")) return; const id = order.id; const ok = await mutate("orders/" + id + "/cancel", "POST", {reason:cancelReason.trim()}, "Zamówienie anulowane; spersonalizowane sztuki odpisano."); if (ok) {setCancelReason(""); await showOrder(id, false);}}}><input aria-label="Powód anulowania" required maxLength={300} placeholder="Powód anulowania" value={cancelReason} onChange={event => setCancelReason(event.target.value)}/><button className="ops-action" disabled={saving || cancelReason.trim().length < 3}>Anuluj z odpisem</button></form></div>}
    {order.production.length > 0 && <><h3 className="ops-detail-title">Zlecenia nanoszenia</h3><div className="ops-detail-production">{order.production.map(task => <div key={task.id}><span>DTF-{String(task.id).padStart(4, "0")} · {task.design} · poz. {task.line_index + 1}</span><StatusBadge status={task.status}/></div>)}</div></>}<h3 className="ops-detail-title">Historia zamówienia</h3><ol className="ops-timeline">{order.events.map(event => <li key={event.id}><strong>{statusText[event.status] || event.status}</strong><small>{formatDate(event.created)}</small></li>)}</ol><button className="ops-action ops-dialog-done" onClick={closeOrder}>Zamknij szczegóły<ArrowRight size={16}/></button></Dialog>}
  </div>;
}
function BarcodeSvg({value, height = 42}:{value:string; height?:number}) {
  const ref = useRef<SVGSVGElement | null>(null);
  const [invalid, setInvalid] = useState(false);
  useEffect(() => {if (!ref.current) return; try {JsBarcode(ref.current, value, {format:"EAN13", height, width:height < 40 ? 1 : 1.2, displayValue:true, fontSize:height < 40 ? 8 : 10, margin:0}); setInvalid(false);} catch {setInvalid(true);}}, [value, height]);
  return <><svg ref={ref} role="img" aria-label={"EAN-13 " + value} style={invalid ? {display:"none"} : undefined}/>{invalid && <span>Nieprawidłowy EAN: {value}</span>}</>;
}
function Label({variant, compact = false}:{variant:Variant; compact?:boolean}) {
  return <div className={"ops-printed-label" + (compact ? " compact" : "")}><div className="ops-label-brand"><strong>Zastal</strong><span>{variant.size}</span></div><div className="ops-label-name">{variant.name}</div><div className="ops-label-codes"><div><BarcodeSvg value={variant.ean} height={compact ? 26 : 42}/></div><QRCodeSVG value={["ZASTAL", variant.sku, variant.ean].join("|")} size={compact ? 40 : 60}/></div><div className="ops-label-foot"><span>{variant.sku}</span><strong>{formatMoney(variant.price)}</strong></div></div>;
}
